CREATE     PROCEDURE [synapse_fo].[usp_Update_BANKACCOUNTTRANS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:32
	Description: Update stored procedure for BANKACCOUNTTRANS from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTID] = stg.[ACCOUNTID],
		tgt.[ACCOUNTINGCURRENCYAMOUNTCORRECT_RU] = stg.[ACCOUNTINGCURRENCYAMOUNTCORRECT_RU],
		tgt.[ACCOUNTSTATEMENT] = stg.[ACCOUNTSTATEMENT],
		tgt.[ACCOUNTSTATEMENTDATE] = stg.[ACCOUNTSTATEMENTDATE],
		tgt.[ACKNOWLEDGEMENTDATE] = stg.[ACKNOWLEDGEMENTDATE],
		tgt.[AMOUNTCORRECT] = stg.[AMOUNTCORRECT],
		tgt.[AMOUNTCUR] = stg.[AMOUNTCUR],
		tgt.[AMOUNTMST] = stg.[AMOUNTMST],
		tgt.[AMOUNTREPORTINGCURRENCY] = stg.[AMOUNTREPORTINGCURRENCY],
		tgt.[BANKPAYMENTREGISTRATIONNUM_LV] = stg.[BANKPAYMENTREGISTRATIONNUM_LV],
		tgt.[BANKTRANSAMOUNTCUR] = stg.[BANKTRANSAMOUNTCUR],
		tgt.[BANKTRANSCURRENCYCODE] = stg.[BANKTRANSCURRENCYCODE],
		tgt.[BANKTRANSTYPE] = stg.[BANKTRANSTYPE],
		tgt.[CANCEL] = stg.[CANCEL],
		tgt.[CANCELPENDING] = stg.[CANCELPENDING],
		tgt.[CENTRALBANKPURPOSECODE_LV] = stg.[CENTRALBANKPURPOSECODE_LV],
		tgt.[CENTRALBANKPURPOSETEXT_LV] = stg.[CENTRALBANKPURPOSETEXT_LV],
		tgt.[CHEQUENUM] = stg.[CHEQUENUM],
		tgt.[CLEAREDDATE] = stg.[CLEAREDDATE],
		tgt.[CORRESPONDENTCOUNTRY_LV] = stg.[CORRESPONDENTCOUNTRY_LV],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[CURRENCYCODE] = stg.[CURRENCYCODE],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DEFAULTDIMENSION] = stg.[DEFAULTDIMENSION],
		tgt.[DEPOSITNUM] = stg.[DEPOSITNUM],
		tgt.[FileName] = stg.[FileName],
		tgt.[INCLUDED] = stg.[INCLUDED],
		tgt.[ISSUMMARIZATION] = stg.[ISSUMMARIZATION],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LEDGERDIMENSION] = stg.[LEDGERDIMENSION],
		tgt.[LEDGERTRANSTYPE] = stg.[LEDGERTRANSTYPE],
		tgt.[LSN] = stg.[LSN],
		tgt.[MANUAL] = stg.[MANUAL],
		tgt.[MODIFIEDBY] = stg.[MODIFIEDBY],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PAYMENTMODE] = stg.[PAYMENTMODE],
		tgt.[PAYMREFERENCE] = stg.[PAYMREFERENCE],
		tgt.[REASONREFRECID] = stg.[REASONREFRECID],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECONCILED] = stg.[RECONCILED],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[REFRECID_RU] = stg.[REFRECID_RU],
		tgt.[REPORTINGCURRENCYAMOUNT_RU] = stg.[REPORTINGCURRENCYAMOUNT_RU],
		tgt.[REPORTINGCURRENCYAMOUNTCORRECT_RU] = stg.[REPORTINGCURRENCYAMOUNTCORRECT_RU],
		tgt.[SKS_BR_ALREADYMARKED] = stg.[SKS_BR_ALREADYMARKED],
		tgt.[SKS_BR_BANKTRANRECID] = stg.[SKS_BR_BANKTRANRECID],
		tgt.[SKS_BR_INTERMMATCH] = stg.[SKS_BR_INTERMMATCH],
		tgt.[SKS_BR_ISSELECTED] = stg.[SKS_BR_ISSELECTED],
		tgt.[SKS_BR_MANUALRECONCILIATIONID] = stg.[SKS_BR_MANUALRECONCILIATIONID],
		tgt.[SKS_BR_MARKEDFROMRECONCILESTATEMENT] = stg.[SKS_BR_MARKEDFROMRECONCILESTATEMENT],
		tgt.[SKS_CCR_ALREADYMARKED] = stg.[SKS_CCR_ALREADYMARKED],
		tgt.[SKS_CCR_BANKTRANRECID] = stg.[SKS_CCR_BANKTRANRECID],
		tgt.[SKS_CCR_INTERMMATCH] = stg.[SKS_CCR_INTERMMATCH],
		tgt.[SKS_CCR_ISCURRENCYADJUSTMENT] = stg.[SKS_CCR_ISCURRENCYADJUSTMENT],
		tgt.[SKS_CCR_ISPARTOFREVERSAL] = stg.[SKS_CCR_ISPARTOFREVERSAL],
		tgt.[SKS_CCR_ISSELECTED] = stg.[SKS_CCR_ISSELECTED],
		tgt.[SKS_CCR_MANUALRECONCILIATIONID] = stg.[SKS_CCR_MANUALRECONCILIATIONID],
		tgt.[SKS_EFTAP_INBOUNDREFNUM] = stg.[SKS_EFTAP_INBOUNDREFNUM],
		tgt.[SKS_IHB_APPROPRIATIONCALCULATED] = stg.[SKS_IHB_APPROPRIATIONCALCULATED],
		tgt.[SKS_IHB_INTERESTCALCULATED] = stg.[SKS_IHB_INTERESTCALCULATED],
		tgt.[SKS_IHB_STATEMENTDATE] = stg.[SKS_IHB_STATEMENTDATE],
		tgt.[SKS_IHB_STATEMENTNUMBER] = stg.[SKS_IHB_STATEMENTNUMBER],
		tgt.[SKS_IHB_VALUEDATE] = stg.[SKS_IHB_VALUEDATE],
		tgt.[SOURCERECID] = stg.[SOURCERECID],
		tgt.[SOURCETABLEID] = stg.[SOURCETABLEID],
		tgt.[SUMMARIZATIONID] = stg.[SUMMARIZATIONID],
		tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TAXGROUP] = stg.[TAXGROUP],
		tgt.[TAXITEMGROUP] = stg.[TAXITEMGROUP],
		tgt.[TRANSDATE] = stg.[TRANSDATE],
		tgt.[TXT] = stg.[TXT],
		tgt.[VOUCHER] = stg.[VOUCHER]
	 FROM [synapse_fo].[BANKACCOUNTTRANS] tgt
		INNER JOIN [staging_fo].[BANKACCOUNTTRANS] stg
			ON  stg.[AccountId] = tgt.[AccountId] 
			AND stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
			AND stg.[RECID] = tgt.[RECID] 
			AND stg.[TransDate] = tgt.[TransDate] 
		
END
